at::Tensor batch_norm_custom_impl_npu(const at::Tensor& x, const at::Tensor& gamma, const at::Tensor& beta) {
    // x: [B, S, H]
    at::Tensor y = at::empty_like(x);
    // mean/var: [S, H]
    auto S = x.size(1);
    auto H = x.size(2);
    at::Tensor mean = at::empty({S, H}, x.options());
    at::Tensor var = at::empty({S, H}, x.options());

    EXEC_NPU_CMD(aclnnBatchNormCustom, x, gamma, beta, y, mean, var);
    return y;
